package org.transittr;
import android.app.*;import android.content.*;import android.os.Build;import java.util.*;
/** One optional foreground-configured favourite monitored in the background. */
public final class ApproachAlert {
 private static final String PREFS="approach-alert-v1",TICK="org.transittr.alert.TICK";
 private static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences(PREFS,0);}
 public static String active(Context c){return prefs(c).getString("id","");}public static int threshold(Context c){return prefs(c).getInt("minutes",0);}
 public static void enable(Context c,String id,int minutes){if(WidgetFavorites.find(c,id)==null||!(minutes==2||minutes==5||minutes==10))throw new IllegalArgumentException("Bildirim ayarı geçersiz");prefs(c).edit().putString("id",id).putInt("minutes",minutes).putBoolean("armed",true).commit();request(c);}
 public static void pause(Context c){String id=active(c);int minutes=threshold(c);prefs(c).edit().remove("id").remove("minutes").remove("armed").putString("paused-id",id).putInt("paused-minutes",minutes).commit();cancel(c);}
 public static boolean resume(Context c){String id=prefs(c).getString("paused-id","");int minutes=prefs(c).getInt("paused-minutes",0);if(WidgetFavorites.find(c,id)==null||!(minutes==2||minutes==5||minutes==10))return false;enable(c,id,minutes);return true;}
 public static void disable(Context c){prefs(c).edit().clear().commit();cancel(c);}
 public static void removed(Context c,String id){if(id.equals(active(c)))disable(c);}
 private static int flags(){return PendingIntent.FLAG_UPDATE_CURRENT|(Build.VERSION.SDK_INT>=23?0x04000000:0);}
 private static PendingIntent alarm(Context c){Intent i=new Intent(c,ApproachReceiver.class).setAction(TICK);return PendingIntent.getBroadcast(c,17301,i,flags());}
 public static void cancel(Context c){((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).cancel(alarm(c));if(Build.VERSION.SDK_INT>=23)try{Class.forName("org.transittr.ModernApproach").getMethod("cancel",Context.class).invoke(null,c);}catch(Exception ignored){}}
 public static void schedule(Context c,boolean immediate){if(active(c).length()==0)return;if(Build.VERSION.SDK_INT>=23){try{Class.forName("org.transittr.ModernApproach").getMethod("schedule",Context.class,Boolean.TYPE).invoke(null,c,Boolean.valueOf(immediate));return;}catch(Exception e){android.util.Log.w("TransitTR","Bildirim işi başlatılamadı",e);return;}}((AlarmManager)c.getSystemService(Context.ALARM_SERVICE)).set(AlarmManager.RTC_WAKEUP,System.currentTimeMillis()+(immediate?1000:60000),alarm(c));}
 public static void request(Context c){schedule(c,true);}
 public static long nearest(JourneyData.Snapshot snapshot,WidgetFavorites.Entry e){long best=Long.MAX_VALUE;for(JourneyData.Vehicle v:snapshot.rows){if(v.passed||v.etaSeconds<0||v.etaSeconds>=86400||v.signalAgeSeconds>180)continue;boolean match=v.line.equalsIgnoreCase(e.line)||e.city==6&&KonyaClient.matches(v.line,e.line)||e.city==0&&v.line.split("-")[0].equalsIgnoreCase(e.line);if(!match||e.city==1&&!IettClient.matchesDirection(v.routeCode,e.direction))continue;if(v.etaSeconds<best)best=v.etaSeconds;}return best;}
 public static synchronized void poll(Context c){String id=active(c);WidgetFavorites.Entry e=WidgetFavorites.find(c,id);if(e==null||threshold(c)<=0){if(id.length()>0)disable(c);return;}try{JourneyData.Snapshot snapshot=WidgetArrivals.fetch(e);if(snapshot.sourceAgeSeconds>180)return;long seconds=nearest(snapshot,e);if(!id.equals(active(c)))return;int limit=threshold(c);boolean armed=prefs(c).getBoolean("armed",true);if(seconds==Long.MAX_VALUE||seconds>(limit+2)*60L){prefs(c).edit().putBoolean("armed",true).commit();return;}if(seconds<=limit*60L&&armed){if(post(c,e,seconds))prefs(c).edit().putBoolean("armed",false).commit();}}catch(Exception e1){android.util.Log.w("TransitTR","Bildirim tahmini alınamadı",e1);}}
 @SuppressWarnings("deprecation") private static boolean post(Context c,WidgetFavorites.Entry e,long seconds)throws Exception{String title=e.line+" durağa yaklaşıyor",body=WidgetFavorites.cityName(e.city)+" · "+e.stop+" · "+(seconds<=0?"durakta":((seconds+59)/60)+" dk");if(Build.VERSION.SDK_INT>=23){return ((Boolean)Class.forName("org.transittr.ModernApproach").getMethod("post",Context.class,String.class,String.class,Intent.class).invoke(null,c,title,body,TransitWidget.open(c,e))).booleanValue();}Notification notification=new Notification(android.R.drawable.ic_dialog_info,title,System.currentTimeMillis());notification.flags|=Notification.FLAG_AUTO_CANCEL;PendingIntent open=PendingIntent.getActivity(c,17301,TransitWidget.open(c,e),flags());notification.setLatestEventInfo(c,title,body,open);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify(17301,notification);return true;}
}
